import type { ZodType } from 'zod';
import type { AnalysisSpec } from './contract';
export type AskLocale = 'auto' | 'en' | 'fr' | 'es' | 'de' | 'pt' | 'ja' | 'zh' | 'ko' | 'ar' | 'ru';
export interface AskSource { id: string; title: string; url: string; reviewed: string }
export interface AskTransfers { direction: 'shield' | 'deshield'; pool: string; start: string; end: string; retrievedAt: string; complete: boolean; groups: { kind: 'latest' | 'largest'; rows: { txid: string; blockHeight: number; blockTime: number; pools: string[]; amountZat: string; amountAuthority: string }[] }[] }
export interface AskDataContext { start: string | null; end: string | null; retrievedAt: string; source: string; label: string }
export interface AskBlocks { status: 'found' | 'not-found' | 'orphaned'; query: { mode: 'latest' | 'recent' | 'detail'; identifier: string | null }; rows: { height: number; hash: string; timestamp: number; transactions: number; size: number; feesZat: string | null; miner: string | null; software: string }[]; retrievedAt?: string }
export interface AskTransactions { status: 'found' | 'not-found'; query: { mode: 'latest' | 'detail'; txid: string | null; limit: number }; rows: { txid: string; status: 'confirmed' | 'indexed' | 'pending' | 'stale' | 'unknown'; blockHeight: number | null; blockHash: string | null; timestamp: number | null; confirmations: number | null; size: number | null; feeZat: string | null; coinbase: boolean | null; pools: string[]; componentsKnown: boolean; transparentInputs: number | null; transparentOutputs: number | null }[]; retrievedAt: string }
export interface LegacyAnalytics { plan: { version: 1; metric: string; start: string; end: string; bucket: 'day' | 'week' | 'month'; order: 'newest' | 'highest' | 'lowest'; limit: number }; label: string; unit: 'transactions' | 'ZEC'; kind: 'count' | 'snapshot'; rows: { date: string; value: string; formatted: string; observedDays: number; observedThrough: string }[]; coverage: { expectedDays: number; observedDays: number; missingDays: number }; retrievedAt: string; methodology: string }
export interface QueryFilter { field: string; op: 'eq' | 'ne' | 'gte' | 'lte'; value: string }
export interface QueryPlan { version: 2; dataset: 'daily' | 'blocks' | 'transactions' | 'flows' | 'swaps'; start: string; end: string; bucket: 'none' | 'day' | 'week' | 'month'; dimensions: string[]; filters: QueryFilter[]; measures: { field: string; operation: 'count' | 'sum' | 'avg' | 'min' | 'max' | 'last'; filters: QueryFilter[] }[]; calculations: { operation: 'ratio' | 'difference'; left: number; right: number }[]; order: { column: number; direction: 'asc' | 'desc' }; limit: number }
export interface QueryResult { plan: QueryPlan; label: string; columns: { key: string; label: string; type: string; unit: string; field?: string }[]; rows: Record<string, { value: string | null; formatted: string; missing?: number }>[]; coverage: { expectedDays: number; observedDays: number | null; missingDays: number | null; indexedThrough: string; completeness: string }; retrievedAt: string; methodology: string }
export type AskAnalytics = LegacyAnalytics | QueryResult;
// Server-written summary of what the previous answer ran; sent back unchanged.
export interface AskTurnScope { version: 1; kind: 'sql' | 'chart' | 'block' | 'transaction'; datasets: string[]; measures: string[]; pools: ('orchard' | 'ironwood' | 'sapling' | 'sprout' | 'transparent')[]; window: { start: string; end: string } | null; period: '30d' | '90d' | '1y' | null; grain: 'day' | 'week' | 'month' | 'year' | null; metric: AnalysisSpec['metric'] | null; subject: string | null }
// Stages /v1/ask/chat may stream before its reply (Accept: application/x-ndjson).
export type AskProgressStage = 'planning' | 'checking' | 'running' | 'repairing' | 'explaining' | 'looking_up' | 'reading';
export interface AskReply { turnScope?: AskTurnScope; handoff?: 'zift' | 'try-zift'; job?: import('./research-job-contract').ResearchJobTicket; research?: import('./research-contract').ResearchResult; analytics?: AskAnalytics; transactions?: AskTransactions; blocks?: AskBlocks; dataContext?: AskDataContext; answer: string; sources: AskSource[]; spec: AnalysisSpec | null; locale: string; mode: 'guided' | 'ai'; transfers?: AskTransfers; evidenceKey?: string; scope?: string; chart?: unknown; route?: string; template?: boolean }
export interface AskTurn extends AskReply { question: string }
export interface ChatRequest { turnScope?: AskTurnScope; currentResearch?: import('./research-contract').ResearchQuery; currentAnalytics?: QueryPlan; transaction?: string; block?: string; question: string; page: string; context: AnalysisSpec | null; locale: AskLocale; history: string[]; challenge?: string }
export const chatRequestSchema: ZodType<ChatRequest>;
export const turnScopeSchema: ZodType<AskTurnScope>;
export const progressStages: AskProgressStage[];
export const locales: string[];
